package com.zhou.craft.config;import com.zhou.craft.security.AuthInterceptor;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Configuration;import org.springframework.web.servlet.config.annotation.*;import java.nio.file.Paths;
@Configuration public class WebConfig implements WebMvcConfigurer{private final AuthInterceptor auth;private final String uploadDir;public WebConfig(AuthInterceptor auth,@Value("${app.upload-dir:uploads}")String uploadDir){this.auth=auth;this.uploadDir=uploadDir;}public void addCorsMappings(CorsRegistry r){r.addMapping("/api/**").allowedOrigins("http://localhost:5173","http://127.0.0.1:5173").allowedMethods("*").allowedHeaders("*");}public void addInterceptors(InterceptorRegistry r){r.addInterceptor(auth).addPathPatterns("/api/**");}public void addResourceHandlers(ResourceHandlerRegistry registry){String location=Paths.get(uploadDir).toAbsolutePath().normalize().toUri().toString();registry.addResourceHandler("/uploads/**").addResourceLocations(location);}}